{
  "overview": "A high-performance, secure URL shortener service built with ASP.NET Core minimal APIs on .NET 10 and Entity Framework Core with SQLite. The service provisions auto-generated base62 codes and custom aliases with optional expiration, redirects callers using HTTP 307 to preserve analytics telemetry, and provides real-time click metrics and health checks. Strict pre-shortening SSRF validation blocks private/loopback network targets, and IP-based rate limiting prevents spam and DoS.",
  "components": [
    {
      "name": "AppDbContext",
      "responsibility": "Configures EF Core model mappings, entity constraints (unique code index, default UTC conversions), and manages SQLite persistence for short links.",
      "module": "src/App/Data/AppDbContext.cs"
    },
    {
      "name": "ShortLink",
      "responsibility": "Represents the persisted domain entity for a shortened link, storing code, target URL, creation time, expiration time, click count, and last visited time.",
      "module": "src/App/Data/ShortLink.cs"
    },
    {
      "name": "UrlValidationService",
      "responsibility": "Validates incoming URLs against strict criteria: ensures HTTP/HTTPS schemes and resolves hostnames via DNS to detect and reject private, loopback, link-local, or multicast IPs to prevent SSRF.",
      "module": "src/App/Services/UrlValidationService.cs"
    },
    {
      "name": "CodeGeneratorService",
      "responsibility": "Generates cryptographically secure, random 7-character Base62 alphanumeric codes and validates user-supplied custom aliases against format rules.",
      "module": "src/App/Services/CodeGeneratorService.cs"
    },
    {
      "name": "LinkService",
      "responsibility": "Coordinates URL validation, alias collisions, code generation, link creation, expiration checks, redirect lookups, click increments, and analytics retrieval.",
      "module": "src/App/Services/LinkService.cs"
    },
    {
      "name": "RateLimitingConfiguration",
      "responsibility": "Configures ASP.NET Core built-in sliding or fixed window rate limiting per client IP for the POST /shorten endpoint, emitting HTTP 429 and Retry-After headers.",
      "module": "src/App/Middleware/RateLimitingConfiguration.cs"
    },
    {
      "name": "LinkEndpoints",
      "responsibility": "Defines Minimal API route mappings for POST /shorten, GET /{code}, GET /analytics/{code}, and GET /health with parameter bindings, status codes, and error formatting.",
      "module": "src/App/Endpoints/LinkEndpoints.cs"
    },
    {
      "name": "Contracts",
      "responsibility": "Declares strongly typed request and response DTOs: ShortenRequest, ShortenResponse, AnalyticsResponse, HealthResponse, and ErrorResponse.",
      "module": "src/App/Models/Contracts.cs"
    },
    {
      "name": "Program",
      "responsibility": "Bootstraps dependency injection, EF Core SQLite connection, rate limiting middleware, routing, database migration on startup, and exposes partial class Program for testing.",
      "module": "src/App/Program.cs"
    },
    {
